import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CQxpk36T.js";const g=JSON.parse('{"title":"This documentation","description":"","frontmatter":{},"headers":[],"relativePath":"en/developpement/documentation.md","filePath":"en/developpement/documentation.md","lastUpdated":1793574169000}'),o={name:"en/developpement/documentation.md"};function n(d,e,r,h,c,l){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="this-documentation" tabindex="-1">This documentation <a class="header-anchor" href="#this-documentation" aria-label="Permalink to &quot;This documentation&quot;">​</a></h1><p>This site is written in Markdown in <code>docs/</code>, with <a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a>. It lives next to the code, on the same branch: an engine change and the page that explains it go into the same commit.</p><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><p>French is at the root of <code>docs/</code>, English in <code>docs/en/</code>. Each translated page keeps <strong>the same path</strong> as the original (<code>docs/guide/terrain.md</code> → <code>docs/en/guide/terrain.md</code>): the language switcher goes from one to the other. Menus and sidebars are built in <code>docs/.vitepress/config.mts</code> from each language&#39;s labels.</p><p>To add a language: a <code>docs/&lt;code&gt;/</code> folder with the translated pages, and its entry in <code>locales</code> with its labels.</p><h2 id="writing" tabindex="-1">Writing <a class="header-anchor" href="#writing" aria-label="Permalink to &quot;Writing&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><p>Opens the site locally (<a href="http://localhost:5173/HAven-docs/" target="_blank" rel="noreferrer">http://localhost:5173/HAven-docs/</a>) with hot reload.</p><table tabindex="0"><thead><tr><th>File</th><th></th></tr></thead><tbody><tr><td><code>docs/.vitepress/config.mts</code></td><td>Title, languages, menu, sidebar, search</td></tr><tr><td><code>docs/.vitepress/theme/custom.css</code></td><td>HAven colours and typography</td></tr><tr><td><code>docs/index.md</code>, <code>docs/en/index.md</code></td><td>Home pages: presentation, film, screenshots</td></tr><tr><td><code>docs/public/</code></td><td>Images, film, icons, served as is</td></tr></tbody></table><p>A new page is added to the sidebar in <code>config.mts</code>, in every language.</p><h2 id="publishing" tabindex="-1">Publishing <a class="header-anchor" href="#publishing" aria-label="Permalink to &quot;Publishing&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:deploy</span></span></code></pre></div><p>Builds the site then pushes it, on its own, to the public repository <a href="https://github.com/Chamallaw/HAven-docs" target="_blank" rel="noreferrer">Chamallaw/HAven-docs</a> (<code>scripts/docs-deploy.mjs</code>); GitHub Pages serves it at <a href="https://chamallaw.github.io/HAven-docs/" target="_blank" rel="noreferrer">https://chamallaw.github.io/HAven-docs/</a>.</p><p>That repository only holds the built site, without history: it is replaced on every publication. HAven&#39;s code stays in its own repository (GitHub doesn&#39;t serve Pages from a private repository on a free account).</p>',14)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
